<?php
declare(strict_types=1);
namespace Essivery\Partner\Controllers;
use Essivery\Api\Core\Auth;use Essivery\Api\Core\Request;use Essivery\Api\Core\Response;use Essivery\Api\Services\AuditService;use Essivery\Partner\Domain\PartnerContext;use Essivery\Partner\Repositories\PartnerHomeServiceRepository;use Essivery\Partner\Services\PartnerHomeServiceService;use Essivery\Partner\Services\PartnerSetupService;
final class PartnerHomeServiceController{public function __construct(private array $config){}public function show(Request $request):never{Response::success($this->service()->get($this->context($request)),200,['requestId'=>$request->requestId]);}public function update(Request $request):never{$auth=Auth::context($request);$audit=new AuditService($this->pdo());$value=$this->service()->update($this->context($request),$request->body,function($meta)use($audit,$auth,$request){$safe=['serviceCodes'=>$meta['serviceCodes'],'serviceCount'=>$meta['serviceCount'],'setupPreference'=>$meta['setupPreference']];$audit->record((int)$auth['user_id'],(int)$auth['identity_id'],'partner_setup.home_service_updated','partner_setup_application',null,$request->requestId,$safe);$audit->record((int)$auth['user_id'],(int)$auth['identity_id'],'partner_setup.home_service_completed','partner_setup_application',null,$request->requestId,$safe);if($meta['preferenceChanged'])$audit->record((int)$auth['user_id'],(int)$auth['identity_id'],'partner_setup.home_service_preference_changed','partner_setup_application',null,$request->requestId,$safe);});Response::success($value,200,['requestId'=>$request->requestId]);}private function service():PartnerHomeServiceService{$pdo=$this->pdo();$definitions=$this->config['partner']['setup']??require dirname(__DIR__).'/config/setup.php';return new PartnerHomeServiceService($pdo,new PartnerHomeServiceRepository($pdo),new PartnerSetupService($pdo,$definitions));}private function context(Request $request):PartnerContext{return$request->attributes['partnerContext'];}private function pdo():\PDO{return$this->config['database']->connection();}}

